'use client';
import {useEffect,useRef,useState} from 'react';
import {validateInvoiceCorrectionReview,sameCorrectionReview} from '@/lib/invoice-correction';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
export type CorrectionTarget={id:string;kind:string;amount:string;date:string};
type Pending={review?:Record<string,unknown>;id:string;scope:HandoffScope;reservation:string;target:CorrectionTarget;period:string;date:string;reason:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function valid(p:Pending,scope:HandoffScope,reservation:string){if(!p||p.scope?.tenant!==scope.tenant||p.scope?.property!==scope.property||p.scope?.actor!==scope.actor||p.reservation!==reservation||!uuid(p.id)||!uuid(p.period)||!uuid(p.target?.id)||!['invoice_application','application','recorded_collection','recorded_refund'].includes(p.target.kind)||typeof p.target.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(p.target.amount)||typeof p.target.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.target.date)||typeof p.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||p.date<p.target.date||typeof p.reason!=='string'||p.reason.trim()!==p.reason||p.reason.length<4||p.reason.length>500)throw Error('Invalid saved correction.');if(p.target.kind==='invoice_application')validateInvoiceCorrectionReview(p.review,scope,reservation,p.target,p.period,p.date);}
function receipt(v:Record<string,unknown>,id:string){if(v.request_id!==id||!uuid(v.journal_id)||typeof v.replayed!=='boolean'||v.moves_money!==false)throw Error('Correction receipt does not match this request.');}
export function FinancialOpeningCorrection({scope,reservation,target,onLocked,onCompleted}:{scope:HandoffScope;reservation:string;target:CorrectionTarget|null;onLocked:(locked:boolean)=>void;onCompleted:()=>void}){
 const [invoiceReview,setInvoiceReview]=useState<Record<string,unknown>|null>(null),[pending,setPending]=useState<Pending|null>(null),[setup,setSetup]=useState<AccountingSetup|null>(null),[period,setPeriod]=useState(''),[date,setDate]=useState(''),[reason,setReason]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const key=['irp.opening.correction.v1',scope.tenant,scope.property,scope.actor,reservation].join(':'),alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw) as Pending;valid(p,scope,reservation);setPending(p);setPeriod(p.period);setDate(p.date);setReason(p.reason)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore correction.')}return()=>{alive.current=false}},[key]);
 useEffect(()=>{onLocked(!ready||busy||!!pending)},[ready,busy,pending,onLocked]);
 useEffect(()=>{setConfirmed(false);setInvoiceReview(null);setMessage('')},[target]);
 async function run(kind:'setup'|'review'|'save'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{const identify=async()=>{const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the account.')};await identify();const base={p_tenant:scope.tenant,p_property:scope.property};
   if(kind==='setup'){const value=readAccountingSetup(await hotelRpc('gl_setup',base),scope.tenant,scope.property);await identify();if(alive.current)setSetup(value);return}
   if(kind==='review'){if(!target||target.kind!=='invoice_application')throw Error('Choose an invoice application.');const review=validateInvoiceCorrectionReview(await hotelRpc('preview_opening_invoice_correction',{...base,p_application:target.id,p_period:period,p_date:date}),scope,reservation,target,period,date);await identify();if(alive.current){setInvoiceReview(review);setConfirmed(false)}return}
   let p=pending;if(!p){if(kind!=='save'||!target||!confirmed)throw Error('Choose an activity and confirm the correction.');p={...(target.kind==='invoice_application'?{review:invoiceReview??undefined}:{}),id:crypto.randomUUID(),scope,reservation,target,period,date,reason:reason.trim()};valid(p,scope,reservation);if(sessionStorage.getItem(key))throw Error('Recover the existing correction first.');sessionStorage.setItem(key,JSON.stringify(p));setPending(p)}
   let complete=false,cancelled=false;
   if(kind==='save'){if(!confirmed)throw Error('Confirm the correction.');if(p.target.kind==='invoice_application')receipt(await hotelRpc('correct_opening_invoice_application',{...base,p_request:p.id,p_review:p.review,p_reason:p.reason}),p.id);else receipt(await hotelRpc('correct_financial_opening_activity',{...base,p_request:p.id,p_kind:p.target.kind==='application'?'application':'external',p_target:p.target.id,p_period:p.period,p_date:p.date,p_reason:p.reason,p_confirmed:true}),p.id);complete=true}
   else{if(kind==='cancel'){if(!cancelConfirmed)throw Error('Confirm request cancellation.');await hotelRpc(p.target.kind==='invoice_application'?'cancel_opening_invoice_correction':'cancel_financial_opening_correction',{...base,p_request:p.id,p_confirmed:true})}const status=await hotelRpc<Record<string,unknown>>(p.target.kind==='invoice_application'?'opening_invoice_correction_status':'financial_opening_correction_status',{...base,p_request:p.id});if(status.schema_version!==1||status.tenant_id!==scope.tenant||status.property_id!==scope.property||status.actor_id!==scope.actor||status.request_id!==p.id||typeof status.found!=='boolean'||typeof status.cancelled!=='boolean'||status.found&&status.cancelled||!status.found&&status.result!==null)throw Error('Correction status does not match this request.');if(status.found){if(p.target.kind==='invoice_application'&&!sameCorrectionReview(status.review,p.review))throw Error('Recovered invoice review changed.');receipt(status.result as Record<string,unknown>,p.id);complete=true}cancelled=status.cancelled}
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setConfirmed(false);setCancelConfirmed(false);setMessage(complete?'Activity correction recorded.':'Correction request cancelled.');if(complete)onCompleted()}else setMessage('No correction found. Retry or cancel the saved request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to complete correction.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 const chosen=pending?.target??target;
 return <section aria-label="Correct migrated activity"><h4>Correct a recorded activity</h4>{chosen?<><p>{chosen.kind.replaceAll('_',' ')} · {bankCloseMoney(chosen.amount)} · {chosen.date}</p><p>This reverses the full recorded activity. It does not move money.</p><button type="button" disabled={busy||!ready||!!pending} onClick={()=>void run('setup')}>Load correction periods</button><fieldset disabled={busy||!ready||!!pending}><label>Correction period<select value={period} onChange={e=>{setPeriod(e.target.value);setConfirmed(false);setInvoiceReview(null)}}><option value="">Choose period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive} (end excluded)</option>)}</select></label><label>Correction date<input type="date" value={date} min={chosen.date} onChange={e=>{setDate(e.target.value);setConfirmed(false);setInvoiceReview(null)}}/></label><label>Correction reason<input value={reason} maxLength={500} onChange={e=>{setReason(e.target.value);setConfirmed(false);setInvoiceReview(null)}}/></label></fieldset>{chosen.kind==='invoice_application'&&<><button type="button" disabled={busy||!ready||!!pending||!period||!date} onClick={()=>void run('review')}>Review invoice correction</button>{(pending?.review??invoiceReview)&&<p role="status">This correction restores {bankCloseMoney(chosen.amount)} in migrated funds and reopens the same amount on the invoice.</p>}</>}<label><input type="checkbox" checked={confirmed} disabled={busy} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this recorded activity is incorrect</label><button type="button" disabled={busy||!ready||!confirmed||chosen.kind==='invoice_application'&&!pending&&!invoiceReview} onClick={()=>void run('save')}>{pending?'Retry activity correction':'Record activity correction'}</button></>:<p>Select an activity from the account above.</p>}{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check correction outcome</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if correction was not recorded</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel correction request</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
